class Solution:
    def wallsAndGates(self, rooms: list[list[int]]) -> None:
        """
        Do not return anything, modify rooms in-place instead.
        """
        m, n = len(rooms), len(rooms[0])
        DIRS = [(-1, 0), (0, -1), (1, 0), (0, 1)]
        queue = deque()
        ROOM = 2147483647

        for i in range(m):
            for j in range(n):
                if rooms[i][j] == 0:
                    queue.append((i, j))

        dis = 1
        while queue:
            k = len(queue)
            for _ in range(k):
                r, c = queue.popleft()
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < m and 0 <= nc < n and rooms[nr][nc] != -1 and rooms[nr][nc] == ROOM:
                        rooms[nr][nc] = dis
                        queue.append((nr, nc))
            dis += 1
